            "description": "el idx del candidato en la lista recibida"
          },
          "confianza": {
            "type": "number"
          },
          "porque": {
            "type": "string"
          }
        }
      }
    },
    "dudaNicho": {
      "type": "boolean"
    },
    "motivo": {
      "type": "string"
    }
  }
}
